const base = '/home/user/.factory/missions/e194b9e3-6a67-42b9-bfc9-dd4e1ac23b0c/';
const repo = '/home/user/code/EllyaOrg/projects/dalimaray/droid-observatory/';
const arch = await tools.Read({ file_path: base+'architecture.md' });
const start = arch.indexOf('| assistant `tool_use` Edit/Create/ApplyPatch');
const end = arch.indexOf('pub fn tray_count');
text('## architecture.md middle\n' + arch.slice(start, end));
const spec = await tools.Read({ file_path: repo+'SPEC.md', line_numbers: true });
const lines = spec.split('\n');
const heads = lines.filter(l => /→#{1,3} /.test(l));
text('## SPEC headings\n' + heads.join('\n'));

const repo = '/home/user/code/EllyaOrg/projects/dalimaray/droid-observatory/';
const [s3, s6, mk, mb, rel] = await Promise.all([
  tools.Read({ file_path: repo+'SPEC.md', offset: 153, limit: 56 }),
  tools.Read({ file_path: repo+'SPEC.md', offset: 553, limit: 92 }),
  tools.Read({ file_path: repo+'Makefile' }),
  tools.Read({ file_path: repo+'.github/workflows/mission-branch.yml' }),
  tools.Read({ file_path: repo+'.github/workflows/release.yml' }),
]);
text('## SPEC §3 common + S\n'+s3);
text('## SPEC §6-8\n'+s6);
text('## Makefile\n'+mk);
text('## mission-branch.yml\n'+mb);
text('## release.yml\n'+rel);

const repo = '/home/user/code/EllyaOrg/projects/dalimaray/droid-observatory/';
const [lanes, doctor, backlog, readme] = await Promise.allSettled([
  tools.Grep({ pattern: 'Time, Waste|Validators, scrutiny|Validators, user testing|^\\| *[1-9] *\\|', path: repo+'ai/prd/droid-observatory-prd.md', output_mode: 'content', line_numbers: true, head_limit: 40 }),
  tools.Read({ file_path: repo+'scripts/doctor.sh' }),
  tools.Grep({ pattern: 'B-016|B-005|B-014', path: repo+'BACKLOG.md', output_mode: 'content', line_numbers: true }),
  tools.Grep({ pattern: 'replay|app-dev|make doctor|make check|clean clone', path: repo+'README.md', output_mode: 'content', line_numbers: true, head_limit: 30 }),
]);
text('## PRD lanes\n' + JSON.stringify(lanes.status==='fulfilled'?lanes.value.map(m=>m.line+': '+m.text):String(lanes.reason), null, 0));
text('## doctor.sh\n' + (doctor.status==='fulfilled'?doctor.value:String(doctor.reason)));
text('## BACKLOG\n' + (backlog.status==='fulfilled'?backlog.value.map(m=>m.line+': '+m.text).join('\n'):String(backlog.reason)));
text('## README\n' + (readme.status==='fulfilled'?readme.value.map(m=>m.line+': '+m.text).join('\n'):String(readme.reason)));
